"""Conservative diagnostics for Russian song lyric text (no third-party dependencies).

Measures written-vowel count; never guesses stress, rhymes, semantic quality, singing,
melody, or metrical correctness. Optional user-verified acute accents can be aligned
with an explicitly supplied syllable/stressed-beat guide, not automatically scored.

Usage: python prosody_probe.py lyric.txt [--guide guide.json]
Guide shape: {"Припев": [{"syllables": 7, "strong_syllables": [2, 5]}, ...]}
Stress positions are 1-indexed vowel ordinals and only reported if annotated in
text by COMBINING ACUTE ACCENT (U+0301) immediately after the vowel.
"""
import argparse
import json
import re
import statistics
import unicodedata
from pathlib import Path

VOWELS = frozenset('аеёиоуыэюяАЕЁИОУЫЭЮЯ')
STRESS_MARK = '\u0301'
SECTION = re.compile(r'^\s*(?:\[([^\]]{1,80})\]|((?:(?:куплет|припев|предприпев|бридж|кода|финал|verse|chorus|prechorus|bridge|outro|instrumental)(?:\s+(?:[IVX]+|\d+|[а-яё]+))?\s*[:—-]?)))\s*$', re.I)
HEADING_KIND = re.compile(r'^(куплет|verse|припев|chorus|предприпев|prechorus|бридж|bridge|кода|outro|финал|instrumental)', re.I)


def vowel_and_manual_stress_positions(line):
    line = unicodedata.normalize('NFD', line)
    syllables, positions = 0, []
    last_was_vowel = False
    for ch in line:
        if ch in VOWELS:
            syllables += 1
            last_was_vowel = True
        elif ch == STRESS_MARK and last_was_vowel:
            positions.append(syllables)
            last_was_vowel = False
        elif unicodedata.combining(ch):
            continue
        else:
            last_was_vowel = False
    return syllables, positions


def classify(title):
    m = HEADING_KIND.match(title.strip())
    if not m:
        return 'unlabeled'
    k = m.group(1).lower()
    if k in ('verse','куплет'):
        return 'verse'
    if k in ('chorus','припев'):
        return 'chorus'
    return k


def normalize_line(s):
    return re.sub(r'\s+', ' ', s.casefold().strip())


def analyze(text, guide=None):
    if guide is not None and not isinstance(guide, dict):
        raise ValueError('guide must be mapping of section title -> list of line targets')
    sections = []
    label = 'unlabeled'
    active = []
    def flush():
        nonlocal active
        if active:
            lengths = [v['vowel_count_proxy'] for v in active]
            median = statistics.median(lengths)
            for line in active:
                diff = line['vowel_count_proxy'] - median
                line['deviation_from_section_median'] = diff
                line['possible_length_outlier'] = abs(diff) >= 3
            sections.append({'section':label,'kind':classify(label),'lines':active})
            active=[]
    for raw in text.splitlines():
        stripped = raw.strip()
        if not stripped:
            flush()
            continue
        m = SECTION.fullmatch(stripped)
        if m:
            flush()
            label = (m.group(1) or m.group(2)).strip()
            continue
        n,stresses = vowel_and_manual_stress_positions(stripped)
        active.append({
            'text':stripped,
            'vowel_count_proxy':n,
            'internal_sentence_stop':bool(re.search(r'[.!?…]\s+\S',stripped)),
            'manual_stress_positions':stresses,
            'stress_status':'PARTIAL_ANNOTATION' if stresses else 'UNKNOWN_UNANNOTATED',
        })
    flush()
    repeats=[]
    grouped = {}
    for s in sections:
        if s['kind'] == 'chorus':
            grouped.setdefault(s['section'].casefold(),[]).append(s)
    for name, ss in grouped.items():
        if len(ss)<2:
            continue
        a=[normalize_line(v['text']) for v in ss[0]['lines']]
        for other in ss[1:]:
            b=[normalize_line(v['text']) for v in other['lines']]
            repeats.append({'section':name,'lines_equal':a==b,'first_line_count':len(a),'other_line_count':len(b),
                            'status':'EXACT_TEXT_REPEAT' if a==b else 'VARIATION_REVIEW_NOT_AUTOMATIC_FAILURE'})
    # Cross-verse rhythmic-cell comparisons (heuristic only, ignores musical intentionality).
    verses=[s for s in sections if s['kind']=='verse']
    homologous=[]
    if len(verses)>1:
        ref=verses[0]
        for nxt in verses[1:]:
            for i,(a,b) in enumerate(zip(ref['lines'],nxt['lines']),start=1):
                gap=b['vowel_count_proxy']-a['vowel_count_proxy']
                if abs(gap)>=2:
                    homologous.append({'verse_a':ref['section'],'verse_b':nxt['section'],'line_number':i,
                                       'vowel_gap':gap,'status':'REVIEW_MUSICAL_CELL_NOT_FAILURE'})
            if len(nxt['lines'])!=len(ref['lines']):
                homologous.append({'verse_a':ref['section'],'verse_b':nxt['section'],
                                   'line_count_gap':len(nxt['lines'])-len(ref['lines']),
                                   'status':'REVIEW_MUSICAL_CELL_NOT_FAILURE'})
    guide_results=[]
    if guide:
        for section in sections:
            requested=guide.get(section['section'])
            if requested is None: continue
            if not isinstance(requested,list):
                raise ValueError('guide section entries must be lists')
            if len(requested)!=len(section['lines']):
                guide_results.append({'section':section['section'],'status':'LINE_COUNT_CONFLICT'})
                continue
            for ix,(line,target) in enumerate(zip(section['lines'],requested),start=1):
                if not isinstance(target,dict) or not isinstance(target.get('syllables'),int):
                    raise ValueError('guide lines must have integer syllables')
                note_count_ok=(line['vowel_count_proxy']==target['syllables'])
                requested_beats=target.get('strong_syllables')
                if requested_beats is None:
                    strong='NOT_REQUESTED'
                elif not line['manual_stress_positions']:
                    strong='UNKNOWN_NO_VERIFIED_ACCENTS'
                else:
                    strong=('ANNOTATED_MATCH' if all(x in requested_beats for x in line['manual_stress_positions'])
                            else 'ANNOTATED_CONFLICT_REVIEW')
                guide_results.append({'section':section['section'],'line_number':ix,
                                      'syllable_count_status':'COUNT_MATCH' if note_count_ok else 'COUNT_MISMATCH',
                                      'stress_alignment_status':strong})
    return {'status':'HEURISTIC_DIAGNOSTIC_ONLY','note':'Written vowel count is not meter, stress, rhyme, singing, or musical proof. Literary/semantic checks are human; partial accents cannot certify complete stress alignment.',
            'sections':sections,'repeated_chorus':repeats,'cross_verse_review':homologous,
            'optional_guide_checks':guide_results,'artistic_verdict':'UNKNOWN_REQUIRES_TRUE_WRITER_AND_LITERARY_CRITIC'}


def main():
    ap=argparse.ArgumentParser()
    ap.add_argument('path',type=Path)
    ap.add_argument('--guide',type=Path)
    args=ap.parse_args()
    guide=json.loads(args.guide.read_text(encoding='utf-8')) if args.guide else None
    print(json.dumps(analyze(args.path.read_text(encoding='utf-8'), guide=guide),ensure_ascii=False,indent=2))

if __name__=='__main__':
    main()
